#!/usr/bin/env python3
"""Author public fixture inputs and separate test oracles; never a student runtime.

Run only when maintaining the corpus. Existing files are intentionally not
regenerated by CI or student self-tests. Word authoring uses the bundled runtime.
"""
import copy
import hashlib
import json
