from docx.shared import Inches, Pt
from lxml import etree

ROOT = Path(__file__).resolve().parents[1]
KIT = ROOT / "samples/acceptance"
INDEX = []
NOW = "2026-10-13T09:00:00+08:00"


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def write(path, value):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def text(relative, body):
    path = KIT / relative; path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(body, encoding="utf-8")
    return path.relative_to(ROOT).as_posix()


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def ref(relative):
    return (KIT / relative).relative_to(ROOT).as_posix()


def case(module, name, category, title, payload, files, status, facts, codes=(), manual="", artifacts=None):
    directory = KIT / module / name
    request = {"schema_version": "bid-training.acceptance-input.v1", "module": module,
               "case_id": name, "source_mode": "DEMO", "project_id": "DEMO-BID-001", "lot_id": "LOT-001",
               "analysis_time": NOW, "payload": payload}
    write(directory / "input.json", request)
    relative = (directory / "input.json").relative_to(ROOT).as_posix()
    files = sorted(set(files + [relative]))
    manifest = {"schema_version": "bid-training.acceptance-case.v1", "module": module,
                "case_id": name, "category": category, "title": title, "input": relative,
                "inputs": [{"path": f, "sha256": sha(ROOT / f)} for f in files],
                "expected": (directory / "expected.json").relative_to(ROOT).as_posix(),
                "manual_review": manual, "artifacts": artifacts or {}}
    write(directory / "expected.json", {"status": status, "facts": facts, "issue_codes": list(codes),
                                        "real_submission_authorized": False})
    write(directory / "case.json", manifest)
    INDEX.append({"module": module, "case_id": name, "category": category,
                  "manifest": (directory / "case.json").relative_to(ROOT).as_posix(), "title": title})


def cert(relative, person, number, until="2028-12-31", hidden=False):
    path = KIT / relative; path.parent.mkdir(parents=True, exist_ok=True)
    image = Image.new("RGB", (1400, 850), "white"); draw = ImageDraw.Draw(image)
    font_path = ROOT / "assets/fonts/NotoSansCJKsc-Regular.otf"
    font = ImageFont.truetype(str(font_path), 34)
    draw.rectangle((35, 35, 1365, 815), outline="#444444", width=3)
    lines = ["FDEX DEMO CERTIFICATE 仅用于公开合成训练", f"Person ID: {person}",
             f"Certificate: {number}", "Qualification: Demo professional service", f"Valid until: {until}",
             "No official issuer or seal  不证明真实资格"]
    for row, line in enumerate(lines):
        draw.text((65, 80 + 105 * row), line, font=font, fill="#222222")
    if hidden:
        # Opaque redaction is deterministic: the date is genuinely unavailable,
        # rather than relying on a subjective OCR confidence threshold.
        draw.rectangle((300, 495, 1300, 590), fill="#b0b0b0")
        draw.text((310, 510), "FIELD NOT LEGIBLE 字段不可读", font=font, fill="black")
    image.save(path)
    return path.relative_to(ROOT).as_posix()


