    case("M03", "change", "change", "其他项目与标包不得混入", {"entries": base_entries + [{"source_id": "SRC-FOREIGN", "path": foreign, "kind": "tender", "version": "1.0", "project_id": "DEMO-OTHER", "lot_id": "LOT-002"}], "required_attachments": []}, files + [foreign], "BLOCKED", {"rejected_ids": ["SRC-FOREIGN"], "registered_ids": facts["registered_ids"]}, ["CONTEXT_MISMATCH"])

    tagged = (ROOT / "samples/e2e/core-normal/tender/tender.md").read_text()
