    expired = cert("shared/ocr/expired.png", "PERSON-03", "OCR-DEMO-003", "2025-12-31")
    corrupt = text("shared/ocr/corrupt.png", "This is intentionally not a readable PNG.\n")
    entries = [{"asset_id": f"OCR-ASSET-{i:02}", "version": "1.0", "image": clear[i-1]} for i in range(1, 5)]
