    case("M09", "unknown-id", "abnormal", "不存在的资产确认不能选用", {**base, "confirmation": confirmation("UNKNOWN-ASSET", company)}, [company], "BLOCKED", {"selected_asset_ids": []}, ["UNKNOWN_ASSET"])


