    results = {"PRICE-01": {"net": "300.00", "tax": "18.00", "gross": "318.00", "over_ceiling": False}, "PRICE-02": {"net": "249.98", "tax": "32.50", "gross": "282.48", "over_ceiling": False}, "PRICE-03": {"net": "110.62", "tax": "14.38", "gross": "125.00", "over_ceiling": False}}
    case("M12", "normal", "normal", "三个独立报价与半分舍入", p, [], "COMPLETE", {"quotes": results, "release_allowed": False}, manual="独立报价不能合成一个总价；金额用Decimal字符串，舍入先分项后税费。PRICE-03含税总价固定125，净价125/1.13取110.62，税额取差额14.38。计算完成不代表报价已批准。")
