def write_cards():
    tasks = {t["module"]: t for t in read(ROOT / "configs/tasks.json") if t["status"] == "ready"}
    lines = ["# 已开放任务专项测试包", "", "本目录只有公开合成输入。输入和参考预期分离；业务实现不得读取 expected.json 或根据 case_id 返回固定答案。", "", "这些材料验证任务增量，不表示业务模块已经实现。完整操作约定见 docs/testing.md。", "", "| 任务 | 用例数 | 测试操作卡 |", "|---|---:|---|"]
    for module, task in tasks.items():
        entries = [c for c in INDEX if c["module"] == module]
        card = [f"# {module} 专项测试操作卡", "", f"任务：{task['title']}；范围：{task['objective']}", "", "## 输入与预期", "", "每个用例的 input.json 只描述输入，case.json 列实际原件路径与SHA256；expected.json 是供测试对比的公开预期，禁止作为运行输入。", "", "| 用例 | 类型 | 目的 | 预期状态 |", "|---|---|---|---|"]
        for c in entries:
            expected = read(ROOT / read(ROOT / c["manifest"])["expected"])
            card.append(f"| [{c['case_id']}]({c['case_id']}/case.json) | {c['category']} | {c['title']} | {expected['status']} |")
        card += ["", "## 直接执行", "", "先验证自己拿到的是完整数据包：", "", "```bash", f"python tools/task_acceptance.py verify-kit --module {module}", "```", "", "开发适配器读取 input.json，调用自己的模块并输出 result.json；结果投影与适配器接口见 docs/testing.md。不需要改生产接口或安装新服务。", "", "```bash", f"python tools/task_acceptance.py run --module {module} --adapter adapters/{module.lower()}.py --output outputs/{module.lower()}-test-01", "```", "", "没有实现适配器时命令会明确失败，不能把verify-kit通过当成功能通过。正常/需复核/异常分支都由检查器判定，不以进程退出0代替业务结果。", "", "已有实际输出也可单例检查：", "", "```bash", f"python tools/task_acceptance.py check --module {module} --case normal --result outputs/my-run/result.json", "```", "", "## PR 必交", "", "运行命令、整套report.json、正常与异常实际输出、新增回归测试、至少一次实际上游文件联调、接口影响和未完成范围。Word任务还交实际DOCX及逐页视觉检查；OCR交像素区域证据和引擎/模型执行记录。", "", "固定输入通过不保证泛化：复审会改变项目、人物、数值或文件顺序。不得复制参考预期冒充实现。代码合并不是业务批准。", ""]
        (KIT / module / "README.md").write_text("\n".join(card), encoding="utf-8")
        lines.append(f"| {module} | {len(entries)} | [{module}](./{module}/README.md) |")
    (KIT / "README.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    write(KIT / "index.json", {"schema_version": "bid-training.acceptance-index.v1", "kit_version": "1.0", "modules": list(tasks), "cases": INDEX})
    from task_descriptions import write_documents
    write_documents()


def main():
    if sys.argv[1:] == ["--seal"]:
        # Explicit author-only mechanical metadata refresh after a reviewed input
        # edit. Does not replace raw data or expected answers; never invoked by CI.
        for record in read(KIT / "index.json")["cases"]:
            path = ROOT / record["manifest"]; manifest = read(path)
            for item in manifest["inputs"]:
                item["sha256"] = sha(ROOT / item["path"])
            write(path, manifest)
        write(KIT / "SHA256SUMS.json", {p.relative_to(ROOT).as_posix(): sha(p) for p in sorted(KIT.rglob("*")) if p.is_file() and p.name != "SHA256SUMS.json"})
        print("Refreshed authoring metadata only; no feature acceptance claimed.")
        return
    if KIT.exists():
        raise SystemExit("Corpus already exists; preserve published byte hashes. Author a new version instead of overwriting.")
    KIT.mkdir(parents=True)
    build_text_kits(); build_material_kits(); build_pricing_kits(); build_word_kits(); build_reuse_and_graph(); write_cards()
    write(KIT / "SHA256SUMS.json", {p.relative_to(ROOT).as_posix(): sha(p) for p in sorted(KIT.rglob("*")) if p.is_file() and p.name != "SHA256SUMS.json"})
    print(f"Authored {len(INDEX)} cases for {len(set(c['module'] for c in INDEX))} ready tasks. Student implementations are NOT tested by this builder.")


if __name__ == "__main__":
    main()
